{
  "schemaVersion": "0.2",
  "slug": "register",
  "name": "Register",
  "status": "experimental",
  "purpose": "Name, email, and password sign-up fragment composed from form, input, password-input, and button.",
  "scenarios": [
    "Create an account with name, email, and password",
    "Confirm the password before submit",
    "Jump to the login scene from the register card"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onSubmit": {
      "type": "event",
      "required": false,
      "description": "Called with name, email, password, and terms after client validation."
    },
    "onLoginClick": {
      "type": "event",
      "required": false,
      "description": "Called when the sign-in action is activated."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Idle sign-up form." },
    { "name": "invalid", "description": "Client validation failed." }
  ],
  "composition": {
    "allowedParents": ["page", "dialog", "card"],
    "allowedChildren": ["form", "input", "password-input", "button", "checkbox", "card", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not collect passwords in a plain text input when password-input is available.",
    "Do not claim 21 authored languages; 19 locales are ICU skeletons.",
    "Password-input currently hardcodes current-password autocomplete; this block cannot override it."
  ],
  "a11y": {
    "role": "form",
    "keyboard": ["Tab moves between fields", "Enter submits the form"],
    "focus": "Fields and actions remain in document order with a visible focus ring.",
    "labeling": "Name, email, password, confirm, terms, and submit have visible labels.",
    "wcag": ["2.1.1", "2.4.7", "3.3.2", "4.1.2"]
  },
  "responsive": {
    "strategy": "Single-column card with max-inline-size; compact viewports keep 44px targets via tokens.",
    "breakpoints": {
      "compact": "Card uses full inline size with 44px targets.",
      "medium": "Card is centered up to 28rem.",
      "large": "Card is centered up to 28rem."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language, never a hardcoded ltr attribute.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "register",
    "states": ["default", "invalid"],
    "intents": ["create-account"]
  }
}

{
  "slug": "register",
  "type": "registry:block",
  "name": "Register",
  "dependencies": ["button", "card", "checkbox", "form", "input", "password-input", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 390,
    "title": "Create an account"
  }
}

import { Button, Card, Checkbox, Form, Input, PasswordInput, Typography } from '@chameleon-ui/components'
import { useState, type FormEvent } from 'react'
import { createBlockCopy } from '../copy.js'
import { registerLocaleTrees } from './locale-map.js'
import './styles.css'

export interface RegisterSubmitValues {
  name: string
  email: string
  password: string
  terms: boolean
}

export interface RegisterProps {
  locale?: string
  onSubmit?: (values: RegisterSubmitValues) => void
  onLoginClick?: () => void
  className?: string
}

function isEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
}

export function Register({ locale = 'en', onSubmit, onLoginClick, className }: RegisterProps) {
  const { t } = createBlockCopy(registerLocaleTrees, locale)
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [terms, setTerms] = useState(false)
  const [created, setCreated] = useState(0)
  const [error, setError] = useState<string | null>(null)
  const classes = ['cu-block-register', className].filter(Boolean).join(' ')

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!name.trim() || !email.trim() || !password || !confirm) {
      setError(t('register.errorRequired'))
      return
    }
    if (!isEmail(email.trim())) {
      setError(t('register.errorInvalid'))
      return
    }
    if (password !== confirm) {
      setError(t('register.errorMismatch'))
      return
    }
    if (!terms) {
      setError(t('register.errorTerms'))
      return
    }
    setError(null)
    setCreated((count) => count + 1)
    onSubmit?.({ name: name.trim(), email: email.trim(), password, terms })
  }

  return (
    <section
      className={classes}
      data-ai-role="register"
      data-ai-intent="create-account"
      data-ai-state={error ? 'invalid' : 'default'}
    >
      <Card className="cu-block-register__card" padding="lg" variant="outlined">
        <Typography variant="heading-1">{t('register.title')}</Typography>
        <Typography variant="body">{t('register.subtitle')}</Typography>
        <p className="cu-block-register__meta">{t('register.accountCount', { count: created })}</p>
        {error ? (
          <p className="cu-block-register__error" role="alert">
            {error}
          </p>
        ) : null}
        <Form onSubmit={handleSubmit} submitLabel={t('register.submit')}>
          <Input autoComplete="name" invalid={Boolean(error)} label={t('register.nameLabel')} onChange={setName} value={name} />
          <Input
            autoComplete="email"
            invalid={Boolean(error)}
            label={t('register.emailLabel')}
            onChange={setEmail}
            type="email"
            value={email}
          />
          <PasswordInput
            hideLabel={t('register.hidePassword')}
            invalid={Boolean(error)}
            label={t('register.passwordLabel')}
            onChange={setPassword}
            showLabel={t('register.showPassword')}
            value={password}
          />
          <PasswordInput
            hideLabel={t('register.hidePassword')}
            invalid={Boolean(error)}
            label={t('register.confirmLabel')}
            onChange={setConfirm}
            showLabel={t('register.showPassword')}
            value={confirm}
          />
          <Checkbox checked={terms} label={t('register.termsLabel')} onChange={setTerms} />
        </Form>
        <div className="cu-block-register__login">
          <Typography variant="caption">{t('register.loginPrompt')}</Typography>
          <Button onClick={onLoginClick} type="button" variant="outline">
            {t('register.loginAction')}
          </Button>
        </div>
      </Card>
    </section>
  )
}

.cu-block-register {
  display: grid;
  justify-items: center;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-register__card {
  display: grid;
  gap: var(--cu-space-3);
  inline-size: min(100%, 28rem);
}

.cu-block-register__meta,
.cu-block-register__error {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-register__error {
  color: var(--cu-color-palette-brand);
}

.cu-block-register__login {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cu-space-2);
}
